const state = {
  mode: "duel",
  database: null,
  rows: [],
  columns: [],
  answers: {},
  selected: null,
  clueIndex: new Map(),
  clueSets: new Map(),
  categoryCache: new Map(),
  availableCache: new Map(),
  nameIndex: new Map(),
  searchPlayers: [],
  photoPromises: new Map(),
  boardHistory: [],
  clueUsage: new Map(),
  indexesReady: false,
  currentPlayer: 1,
  usedPlayerNames: new Set(),
  gameOver: false,
  consecutivePasses: 0,
  winner: null,
  winningLine: [],
  revealWinningLine: false,
  databaseReady: false,
  matchStarted: false,
  players: {
    1: { name: "Speler 1", pawn: "⚽" },
    2: { name: "Speler 2", pawn: "🏆" }
  }
};

const FootballMindDuelStats = (() => {
  const storageKey = 'footballmind-duel-results-v1';
  let match = null;
  let warned = false;
  function read() {
    const parsed = JSON.parse(localStorage.getItem(storageKey) || '[]');
    if (!Array.isArray(parsed)) throw Error('Ongeldig statistiekenbestand');
    return parsed.filter(result => result && typeof result.id === 'string' && [0,1,2].includes(result.winner) && Array.isArray(result.players) && result.players.length === 2 && result.players.every(player => typeof player.name === 'string' && ['correct','wrong','passes'].every(key => Number.isInteger(player[key]) && player[key] >= 0)));
  }
  function begin() {
    if (state.mode === 'solo' || !state.matchStarted) { match = null; return; }
    match = {
      mode: state.mode === "teams" ? "teams" : "duel",
      id: crypto.randomUUID ? crypto.randomUUID() : Date.now() + '-' + Math.random(),
      date: new Date().toISOString(),
      difficulty: getElement('difficulty')?.value || 'medium',
      players: [1,2].map(number => ({name: state.players[number].name, correct:0, wrong:0, passes:0})),
      saved: false
    };
  }
  function answer(kind) {
    if (!match || match.saved || state.mode === 'solo' || state.gameOver || !state.matchStarted) return;
    match.players[state.currentPlayer - 1][kind]++;
  }
  function finish() {
    if (!match || match.saved || state.mode === 'solo' || !state.gameOver) return;
    try {
      const results = read();
      if (!results.some(result => result.id === match.id)) {
        results.push({id:match.id, mode:match.mode, date:match.date, difficulty:match.difficulty, winner:state.winner || 0, players:match.players});
        localStorage.setItem(storageKey, JSON.stringify(results));
      }
      match.saved = true;
    } catch {
      if (!warned) { showMessage('Statistieken opslaan lukt niet. Controleer of lokale opslag in deze browser is toegestaan.', true); warned = true; }
    }
  }
  function totals(mode = state.mode === "teams" ? "teams" : "duel") {
    const players = new Map();
    for (const result of read().filter(result => (result.mode || "duel") === mode)) {
      result.players.forEach((player,index) => {
        const key = player.name.trim().toLocaleLowerCase('nl');
        if (!players.has(key)) players.set(key, {name:player.name, played:0, wins:0, losses:0, draws:0, correct:0, wrong:0, passes:0, streak:0, best:0});
        const total = players.get(key);
        total.played++;
        total.correct += player.correct;
        total.wrong += player.wrong;
        total.passes += player.passes;
        if (result.winner === index + 1) {total.wins++;total.streak++;total.best=Math.max(total.best,total.streak);}
        else {total.streak=0;if(result.winner===0)total.draws++;else total.losses++;}
      });
    }
    return [...players.values()];
  }
  function accuracy(player) {
    const attempts = player.correct + player.wrong;
    return attempts ? Math.round(player.correct / attempts * 100) + '%' : '—';
  }
  function show() {
    let data;
    try { data = totals(); } catch { showMessage('De opgeslagen statistieken kunnen niet worden gelezen.', true); return; }
    document.getElementById('fmDuelStatistics')?.remove();
    const dialog = document.createElement('dialog');
    dialog.id = 'fmDuelStatistics';
    dialog.style.cssText = 'width:min(920px,94vw);max-height:85vh;overflow:auto;padding:24px;background:#21180f;color:#ffe5a1;border:1px solid #c99a3c;border-radius:16px';
    const heading = document.createElement('h2');heading.textContent=state.mode === 'teams' ? 'Statistieken teams 5×5' : 'Statistieken 1 tegen 1';dialog.appendChild(heading);
    const note = document.createElement('p');
    note.textContent = 'Afgeronde wedstrijden vanaf deze update, per spelersnaam. Opgeslagen in deze browser op dit apparaat. Nauwkeurigheid telt goede en foute antwoorden.';
    dialog.appendChild(note);
    const wrapper = document.createElement('div');wrapper.style.overflowX='auto';
    const table = document.createElement('table');table.style.cssText='width:100%;border-collapse:collapse;text-align:left;white-space:nowrap';
    const header = document.createElement('tr');
    for (const label of ['Speler','Gespeeld','Gewonnen','Verloren','Remise','Beste reeks','Nauwkeurigheid','Gepast']) {const cell=document.createElement('th');cell.textContent=label;cell.style.padding='10px';header.appendChild(cell);}
    table.appendChild(header);
    for (const player of data.sort((a,b)=>b.wins-a.wins || a.name.localeCompare(b.name,'nl'))) {
      const row=document.createElement('tr');
      for (const value of [player.name,player.played,player.wins,player.losses,player.draws,player.best,accuracy(player),player.passes]) {const cell=document.createElement('td');cell.textContent=value;cell.style.cssText='padding:10px;border-top:1px solid #695330';row.appendChild(cell);}
      table.appendChild(row);
    }
    wrapper.appendChild(table);dialog.appendChild(wrapper);
    if (!data.length) {const empty=document.createElement('p');empty.textContent='Nog geen afgeronde wedstrijden opgeslagen.';dialog.appendChild(empty);}
    const form=document.createElement('form');form.method='dialog';const close=document.createElement('button');close.textContent='Sluiten';form.appendChild(close);dialog.appendChild(form);
    document.body.appendChild(dialog);dialog.showModal();
  }
  function update() {
    if (state.mode === 'solo') return;
    finish();
    const panel=document.querySelector('.fm-stats-panel');
    if (panel) {
      const name=state.players[state.currentPlayer].name;
      let data;
      try { data=totals().find(player=>player.name.trim().toLocaleLowerCase('nl')===name.trim().toLocaleLowerCase('nl')); } catch { return; }
      panel.replaceChildren();
      const title=document.createElement('h2');title.textContent='STATISTIEKEN — '+name;panel.appendChild(title);
      for(const [label,value] of [['Gespeeld',data?.played||0],['Gewonnen',data?.wins||0],['Verloren',data?.losses||0],['Remise',data?.draws||0],['Beste reeks',data?.best||0],['Nauwkeurigheid',data?accuracy(data):'—']]) {
        const row=document.createElement('div'),caption=document.createElement('span'),number=document.createElement('b');caption.textContent=label;number.textContent=value;row.appendChild(caption);row.appendChild(number);panel.appendChild(row);
      }
    }
    for(const button of document.querySelectorAll('.fm-bottom-nav button')) {
      if(!button.dataset.duelStats && /statistieken/i.test(button.textContent)) {button.dataset.duelStats='true';button.addEventListener('click',show);}
    }
  }
  return {begin,answer,finish,totals,accuracy,update};
})();

const getElement = (id) => document.getElementById(id);

function normalise(value) {
  return FootballMindData.norm(value);
}

