function automaticAwardsForName(name) {
  const key = normalise(cleanPlayerName(name));
  return [
    ...(FOOTBALLMIND_PLAYER_AWARDS[key] || []),
    ...(FOOTBALLMIND_CHAMPIONS_LEAGUE_WINNERS.has(key)
      ? ["Champions League winnaar"]
      : [])
  ];
}

