function mergeUniqueValues(target, source) {
  (source || []).forEach((value) => {
    if (!target.some((item) => normalise(item) === normalise(value))) {
      target.push(value);
    }
  });
}

function mergeLegendPlayers(legendPlayers = LEGEND_PLAYERS) {
  // Bouw één naamindex. De oude versie scande voor iedere legende de volledige
  // spelerslijst opnieuw; bij honderden legendes blokkeerde dat de browser.
  const nameBuckets = new Map();
  const indexPlayerNames = (player) => {
    [player.name, ...(player.aliases || [])]
      .map((name) => normalise(cleanPlayerName(name)))
      .filter(Boolean)
      .forEach((key) => {
        if (!nameBuckets.has(key)) nameBuckets.set(key, []);
        if (!nameBuckets.get(key).includes(player)) nameBuckets.get(key).push(player);
      });
  };
  state.database.players.forEach(indexPlayerNames);

  (legendPlayers || []).forEach((legend, index) => {
    const identityKey = legend.identityKey || "";
    const automaticAwards = automaticAwardsForName(legend.name);
    const legendAwards = [...new Set([...(legend.awards || []), ...automaticAwards])];
    const legendNames = new Set(
      [legend.name, ...(legend.aliases || []), ...(legend.matchNames || [])]
        .map((name) => normalise(cleanPlayerName(name)))
        .filter(Boolean)
    );

    let sameNameRecords = [...new Set(
      [...legendNames].flatMap((name) => nameBuckets.get(name) || [])
    )].filter((player) => {
      if (identityKey && player.fmLegendIdentity && player.fmLegendIdentity !== identityKey) {
        return false;
      }
      return true;
    });

    // Bij gelijknamige spelers eerst op land en daarna op club onderscheiden.
    // Zo blijven Luis Suárez (Uruguay) en Luis Suárez Miramontes (Spanje)
    // twee afzonderlijke spelersprofielen.
    if (sameNameRecords.length > 1) {
      const legendCountries = new Set((legend.internationalTeams || []).map(normalise));
      const countryMatches = sameNameRecords.filter((player) =>
        (player.internationalTeams || []).some((country) => legendCountries.has(normalise(country)))
      );

      if (countryMatches.length) {
        sameNameRecords = countryMatches;
      } else {
        const legendClubs = new Set((legend.clubs || []).map(clueKey));
        const clubMatches = sameNameRecords.filter((player) =>
          (player.clubs || []).some((club) => legendClubs.has(clueKey(club)))
        );
        if (clubMatches.length) sameNameRecords = clubMatches;
      }
    }

    if (sameNameRecords.length) {
      sameNameRecords.forEach((player) => {
        player.clubs = player.clubs || [];
        player.internationalTeams = player.internationalTeams || [];
        player.aliases = player.aliases || [];
        player.awards = player.awards || [];
        player.competitions = player.competitions || [];

        mergeUniqueValues(player.clubs, legend.clubs);
        mergeUniqueValues(player.internationalTeams, legend.internationalTeams);
        mergeUniqueValues(player.aliases, legend.aliases);
        mergeUniqueValues(player.awards, legendAwards);
        mergeUniqueValues(player.competitions, legend.competitions);
        if (!playerPhotoUrl(player) && playerPhotoUrl(legend)) {
          player.image = playerPhotoUrl(legend);
        }
        player.legend = true;
        if (identityKey) player.fmLegendIdentity = identityKey;
      });
    } else {
      const newPlayer = {
        id: `legend-${identityKey || index}-${normalise(legend.name).replace(/\s+/g, "-")}`,
        name: legend.name,
        aliases: legend.aliases || [],
        clubs: legend.clubs || [],
        internationalTeams: legend.internationalTeams || [],
        awards: legendAwards,
        competitions: legend.competitions || [],
        image: playerPhotoUrl(legend) || null,
        legend: true,
        ...(identityKey ? { fmLegendIdentity: identityKey } : {})
      };
      state.database.players.push(newPlayer);
      indexPlayerNames(newPlayer);
    }
  });
}

function applyAutomaticAwardsToDatabase() {
  (state.database.players || []).forEach((player) => {
    player.awards = player.awards || [];
    const names = [player.name, ...(player.aliases || [])];
    names.forEach((name) => mergeUniqueValues(player.awards, automaticAwardsForName(name)));
  });
}

