function applyCareerFixesToDatabase() {
  const players = state.database.players || [];
  const byName = new Map();
  players.forEach((player) => {
    [player.name, ...(player.aliases || [])].forEach((name) => {
      const key = normalise(cleanPlayerName(name));
      if (key && !byName.has(key)) byName.set(key, player);
    });
  });

  FOOTBALLMIND_PLAYER_CAREER_FIXES.forEach((fix, index) => {
    const keys = [fix.name, ...(fix.aliases || [])]
      .map((name) => normalise(cleanPlayerName(name)));
    let player = keys.map((key) => byName.get(key)).find(Boolean);

    if (!player) {
      player = {
        id: `career-fix-${index}-${normalise(fix.name).replace(/\s+/g, "-")}`,
        name: fix.name,
        aliases: [], clubs: [], internationalTeams: [], awards: [], competitions: []
      };
      players.push(player);
    }

    player.aliases = player.aliases || [];
    player.clubs = player.clubs || [];
    player.internationalTeams = player.internationalTeams || [];
    mergeUniqueValues(player.aliases, fix.aliases);
    mergeUniqueValues(player.clubs, fix.clubs);
    mergeUniqueValues(player.internationalTeams, fix.internationalTeams);
  });
}

function playerMatchesClue(player, clue) {
  return FootballMindData.playerMatchesClue(player, clue, state.database?.clueAliases || FOOTBALLMIND_CLUE_ALIASES);
}

function validPlayers(rowClue, columnClue) {
  const rowKey = clueKey(rowClue);
  const columnKey = clueKey(columnClue);
  const rowPlayers = state.clueIndex.get(rowKey) || [];
  const columnSet = state.clueSets.get(columnKey);

  if (!columnSet) return [];
  return rowPlayers.filter((player) => columnSet.has(player));
}

function countValidPlayers(rowClue, columnClue, stopAt = Infinity) {
  const rowKey = clueKey(rowClue);
  const columnKey = clueKey(columnClue);
  const rowPlayers = state.clueIndex.get(rowKey) || [];
  const columnSet = state.clueSets.get(columnKey);

  if (!columnSet) return 0;

  let count = 0;
  for (const player of rowPlayers) {
    if (columnSet.has(player)) {
      count += 1;
      if (count >= stopAt) return count;
    }
  }
  return count;
}

function addPlayerToIndexes(player) {
  const fields = ["clubs", "internationalTeams", "awards", "competitions"];

  fields.forEach((field) => {
    (player[field] || []).forEach((value) => {
      const key = clueKey(value);
      if (!key) return;

      if (!state.clueIndex.has(key)) state.clueIndex.set(key, []);
      state.clueIndex.get(key).push(player);
    });
  });

  const displayName = cleanPlayerName(player.name);
  const aliases = (player.aliases || []).map(cleanPlayerName).filter(Boolean);
  const exactNames = [displayName, ...aliases];

  exactNames.forEach((name) => {
    const key = normalise(name);
    if (!key) return;
    if (!state.nameIndex.has(key)) state.nameIndex.set(key, []);
    state.nameIndex.get(key).push(player);
  });

  state.searchPlayers.push(FootballMindData.searchEntry(player));
}

async function buildClueIndexAsync(progressStart = 82, progressEnd = 96) {
  state.clueIndex = new Map();
  state.clueSets = new Map();
  state.categoryCache = new Map();
  state.availableCache = new Map();
  state.nameIndex = new Map();
  state.searchPlayers = [];

  const players = state.database.players || [];
  const chunkSize = 1800;

  for (let i = 0; i < players.length; i += chunkSize) {
    const end = Math.min(i + chunkSize, players.length);

    for (let j = i; j < end; j += 1) {
      addPlayerToIndexes(players[j]);
    }

    const fraction = players.length ? end / players.length : 1;
    const pct = progressStart + fraction * (progressEnd - progressStart);
    setLoadProgress(pct, "Spelers indexeren…");

    // Geef Chrome echt tijd om balk, percentage en UI te tekenen.
    await new Promise((resolve) => setTimeout(resolve, 0));
  }

  state.clueIndex.forEach((playersForClue, key) => {
    state.clueSets.set(key, new Set(playersForClue));
  });

  state.indexesReady = true;
}

function buildClueIndex() {
  // Alleen nood-fallback. Normaal wordt de async variant tijdens het laden gebruikt.
  if (state.indexesReady) return;

  state.clueIndex = new Map();
  state.clueSets = new Map();
  state.categoryCache = new Map();
  state.availableCache = new Map();
  state.nameIndex = new Map();
  state.searchPlayers = [];

  (state.database.players || []).forEach(addPlayerToIndexes);
  state.clueIndex.forEach((playersForClue, key) => {
    state.clueSets.set(key, new Set(playersForClue));
  });
  state.indexesReady = true;
}

function categoryValues(fields, minimum = 10) {
  const cacheKey = `${fields.join("|")}::${minimum}`;
  if (state.categoryCache.has(cacheKey)) {
    return state.categoryCache.get(cacheKey);
  }

  const fieldSet = new Set(fields);
  const values = new Map();

  state.database.players.forEach((player) => {
    fields.forEach((field) => {
      (player[field] || []).forEach((value) => {
        const raw = String(value || "").trim();
        const key = clueKey(raw);
        if (!key) return;

        const existing = values.get(key);
        if (existing) {
          existing.count += 1;
        } else {
          values.set(key, { value: raw, count: 1 });
        }
      });
    });
  });

  const result = [...values.values()]
    .filter((item) => item.count >= minimum)
    .sort((a, b) => b.count - a.count)
    .map((item) => item.value);

  state.categoryCache.set(cacheKey, result);
  return result;
}

function shuffled(values) {
  const copy = [...values];
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

function availableClues(preferred, fields) {
  const cacheKey = `${fields.join("|")}::${preferred.join("|")}`;
  if (state.availableCache.has(cacheKey)) {
    return state.availableCache.get(cacheKey);
  }

  const available = new Map();

  preferred.forEach((wanted) => {
    const wantedKey = clueKey(wanted);
    if (state.clueIndex.has(wantedKey)) {
      const firstPlayer = (state.clueIndex.get(wantedKey) || [])[0];
      let displayValue = wanted;

      if (firstPlayer) {
        for (const field of fields) {
          const found = (firstPlayer[field] || []).find(
            (value) => clueKey(value) === wantedKey
          );
          if (found) {
            displayValue = found;
            break;
          }
        }
      }

      available.set(wantedKey, displayValue);
    }
  });

  const result = preferred
    .map((value) => available.get(clueKey(value)))
    .filter(Boolean);

  state.availableCache.set(cacheKey, result);
  return result;
}


