const FOOTBALLMIND_IDENTITIES = {
  TM3140: {name: 'Ronaldo Nazário', fullName: 'Ronaldo Luís Nazário de Lima', position: 'Spits', birthYear: '1976', photoPage: 'Ronaldo (Brazilian footballer)', aliases: ['Ronaldo', 'Ronaldo Nazario', 'R9', 'O Fenômeno']},
  TM5800: {name: 'Dida', fullName: 'Nélson de Jesus Silva', position: 'Keeper', birthYear: '1973', photoPage: 'Dida (footballer, born 1973)', aliases: ['Nelson Dida', 'Nelson de Jesus Silva']}
};

function enrichFootballMindIdentities(database) {
  const counts = new Map();
  for (const player of database.players) {
    const key = normalise(cleanPlayerName(player.name));
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  for (const player of database.players) {
    const metadata = FOOTBALLMIND_POSITION_PROFILES[player.id];
    if (metadata) {
      player.position = metadata.position;
      if (metadata.image) player.image = metadata.image;
      if (metadata.photoPage) player.photoPage = metadata.photoPage;
    }
    const originalName = player.name;
    player.ambiguousName = counts.get(normalise(cleanPlayerName(originalName))) > 1;
    const identity = FOOTBALLMIND_IDENTITIES[player.id];
    if (identity) {
      const aliases = [...new Set([originalName, ...(player.aliases || []), ...identity.aliases, identity.fullName])];
      Object.assign(player, identity, {aliases, searchPriority: 1000});
      // Discard old name-based portraits so the exact identity page is used.
      player.image = metadata?.image || null;
    }
  }
  database.nameLookup = {};
  database.players.forEach((player, index) => {
    for (const name of new Set([player.name, ...(player.aliases || [])].map(normalise))) {
      (database.nameLookup[name] ||= []).push(index);
    }
  });
}

function footballMindPlayerDetails(player) {
  return player.position || player.playingPosition || player.role || "Positie onbekend";
}

function showMissedFootballMindAnswers() {
  if (!state.gameOver) return;
  closeWinnerModal();
  const old = document.getElementById('fmMissedAnswers');
  if (old) old.remove();
  const dialog = document.createElement('dialog');
  dialog.id = 'fmMissedAnswers';
  dialog.style.cssText = 'width:min(760px,92vw);max-height:85vh;overflow:auto;background:#21180f;color:#ffe5a1;border:1px solid #c99a3c;border-radius:16px;padding:24px';
  const title = document.createElement('h2');
  title.textContent = 'Gemiste antwoorden';
  dialog.appendChild(title);
  let missed = 0;
  state.rows.forEach((row, r) => state.columns.forEach((column, c) => {
    if (state.answers[`${r}-${c}`]) return;
    missed++;
    const section = document.createElement('details');
    const heading = document.createElement('summary');
    heading.textContent = row + ' × ' + column;
    heading.style.cssText = 'cursor:pointer;font-weight:bold;padding:12px 0';
    section.appendChild(heading);
    section.addEventListener('toggle', () => {
      if (!section.open || section.dataset.loaded) return;
      section.dataset.loaded = 'true';
      const candidates = validPlayers(row, column).filter(player => databaseAllowsReuse() || !Object.values(state.answers).some(answer => answer?.id === player.id || answer?.playerId === player.id));
      candidates.sort((a, b) => (b.searchPriority || 0) - (a.searchPriority || 0) || a.name.localeCompare(b.name, 'nl'));
      const list = document.createElement('ul');
      for (const player of candidates) {
        const item = document.createElement('li');
        item.textContent = player.name + ' — ' + footballMindPlayerDetails(player);
        item.style.cssText = 'padding:8px 0;white-space:pre-line';
        list.appendChild(item);
      }
      if (!candidates.length) list.textContent = 'Geen ongebruikt antwoord gevonden in de database.';
      section.appendChild(list);
    });
    dialog.appendChild(section);
  }));
  if (!missed) {
    const text = document.createElement('p');
    text.textContent = 'Alle vakjes zijn ingevuld.';
    dialog.appendChild(text);
  }
  const close = document.createElement('button');
  close.textContent = 'Sluiten';
  close.addEventListener('click', () => dialog.close());
  dialog.appendChild(close);
  document.body.appendChild(dialog);
  dialog.showModal();
}

function databaseAllowsReuse() {
  return state.database?.rules?.allowPlayerReuse !== false;
}

function playerPhotoUrl(player) {
  return String(
    player?.image ||
    player?.imageUrl ||
    player?.photo ||
    (player?.name && FOOTBALLMIND_CURATED_PLAYER_PHOTOS[normalise(cleanPlayerName(player.name))]) ||
    ""
  ).trim();
}

// De fotolaag werkt ook voor spelers die niet in de brondata een afbeelding hebben.
// De eerste vaste bron is FotMob; voor de rest wordt een Wikipedia-portret op naam
// opgehaald en lokaal gecachet, zodat dezelfde speler niet steeds opnieuw wordt gezocht.
const FOOTBALLMIND_CURATED_PLAYER_PHOTOS = {
  "cristiano ronaldo": "https://images.fotmob.com/image_resources/playerimages/30893.png"
};

function footballMindPhotoCache() {
  try {
    return JSON.parse(localStorage.getItem("footballmind-player-photos-v2") || "{}");
  } catch (error) {
    return {};
  }
}

function saveFootballMindPhoto(name, url) {
  if (!name || !url) return;
  try {
    const cache = footballMindPhotoCache();
    cache[normalise(name)] = url;
    localStorage.setItem("footballmind-player-photos-v2", JSON.stringify(cache));
  } catch (error) {
    // Private browsing of een geblokkeerde opslag mag de fotolaag niet breken.
  }
}

async function resolvePlayerPhoto(player) {
  const direct = playerPhotoUrl(player);
  if (direct) {
    player.image = direct;
    return direct;
  }

  const name = cleanPlayerName(player?.name);
  const key = normalise(player?.id ? `${player.id}:${player.photoPage || name}` : (player.photoPage || name));
  if (!name) return "";

  if (player.ambiguousName && !player.photoPage) return "";
  const cached = footballMindPhotoCache()[key];
  if (cached) {
    player.image = cached;
    return cached;
  }
  if (state.photoPromises.has(key)) return state.photoPromises.get(key);

  if (player.ambiguousName && !player.photoPage) return "";
  const pageTitle = player.photoPage || name;
  const promise = fetch(
    `https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(pageTitle.replace(/\s+/g, "_"))}`,
    { headers: { Accept: "application/json" } }
  )
    .then((response) => (response.ok ? response.json() : null))
    .then((data) => {
      if (!data || data.type === "disambiguation") return "";
      const url = data.thumbnail?.source || data.originalimage?.source || "";
      if (url) {
        player.image = url;
        saveFootballMindPhoto(key, url);
      }
      return url;
    })
    .catch(() => "");

  state.photoPromises.set(key, promise);
  return promise;
}

function hydratePlayerPhoto(image, player) {
  const direct = playerPhotoUrl(player);
  if (direct) {
    image.src = direct;
    image.hidden = false;
    return;
  }

  resolvePlayerPhoto(player).then((url) => {
    if (!url || !image.isConnected) return;
    image.src = url;
    image.hidden = false;
  });
}

function escapeHtmlAttribute(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

