function fmClueVisual(value) {
  const raw = String(value || "").trim();
  const n = normalise(raw);

  const flags = {
    "nederland":"🇳🇱","engeland":"🏴","frankrijk":"🇫🇷","duitsland":"🇩🇪",
    "spanje":"🇪🇸","italie":"🇮🇹","italië":"🇮🇹","portugal":"🇵🇹",
    "brazilie":"🇧🇷","brazilië":"🇧🇷","argentinie":"🇦🇷","argentinië":"🇦🇷",
    "belgie":"🇧🇪","belgië":"🇧🇪","uruguay":"🇺🇾","kroatie":"🇭🇷","kroatië":"🇭🇷",
    "denemarken":"🇩🇰","zweden":"🇸🇪","polen":"🇵🇱","wales":"🏴","schotland":"🏴"
  };

  const country = FOOTBALLMIND_COUNTRY_FLAG_MAPS[n];
  if (country) {
    return { type: "country", name: country[0], flagMap: country[1], icon: country[2] };
  }
  if (flags[n]) return { icon: flags[n], type: "country" };

  if (n.includes("topscorer")) {
    const leagueFlag = FOOTBALLMIND_TOPSCORER_FLAGS.find(([league]) => n.includes(league));
    const leagueName = raw.replace(/^topscorer\s*/i, "").trim();
    return {
      type: "award",
      name: raw,
      awardTitle: "Topscorer",
      awardSubtitle: leagueName,
      specialArt: "images/specials/topscorer.png",
      icon: "🥇",
      flagCode: leagueFlag ? leagueFlag[1] : "",
      flagName: leagueFlag ? leagueFlag[2] : ""
    };
  }

  const special = FOOTBALLMIND_SPECIAL_ART[n];
  if (special) {
    return { type: "award", name: raw, specialArt: special[0], icon: special[1] };
  }

  const competition = FOOTBALLMIND_COMPETITION_LOGOS[n];
  if (competition) {
    return {
      type: "competition",
      name: competition[0],
      logo: `https://images.fotmob.com/image_resources/logo/leaguelogo/${competition[1]}.png`
    };
  }

  const club = FOOTBALLMIND_CLUB_LOGOS[n];
  if (club) {
    return {
      type: "club",
      name: club[0],
      logo: `https://images.fotmob.com/image_resources/logo/teamlogo/${club[1]}.png`
    };
  }

  return { icon: "⚽", type: "club" };
}

function fmClueMarkup(value) {
  const visual = fmClueVisual(value);
  const clueLabel = visual.awardTitle
    ? `<span class="fm-award-title">${visual.awardTitle}</span>${visual.awardSubtitle ? `<span class="fm-award-subtitle">${visual.awardSubtitle}</span>` : ""}`
    : (visual.name || String(value || ""));
  const visualMarkup = visual.specialArt
    ? `<div class="fm-special-art-box">
         <img class="fm-special-art" src="${visual.specialArt}" data-fallback-src="../${visual.specialArt}" alt="${visual.name}" loading="eager"
           onerror="if(!this.dataset.fallbackTried){this.dataset.fallbackTried='1';this.src=this.dataset.fallbackSrc}else{this.closest('.fm-special-art-box').classList.add('art-error');this.remove()}">
         <span class="fm-special-art-fallback" aria-hidden="true">${visual.icon}</span>
         ${visual.flagCode ? `<span class="fm-special-flag-badge fm-flag-${visual.flagCode}" role="img" aria-label="${visual.flagName}"></span>` : ""}
       </div>`
    : visual.flagMap
    ? `<div class="fm-country-map-box">
         <img class="fm-country-map" src="${visual.flagMap}" alt="${visual.name} in de vorm van de landskaart" loading="eager"
           onerror="this.closest('.fm-country-map-box').classList.add('map-error');this.remove()">
         <span class="fm-country-map-fallback" aria-hidden="true">${visual.icon}</span>
       </div>`
    : visual.logo && visual.type === "competition"
    ? `<div class="fm-competition-logo-box">
         <img class="fm-competition-logo" src="${visual.logo}" alt="Logo ${visual.name}" loading="eager"
           onerror="this.closest('.fm-competition-logo-box').classList.add('logo-error');this.remove()">
         <span class="fm-competition-logo-fallback" aria-hidden="true">🏆</span>
       </div>`
    : visual.logo
    ? `<div class="fm-clue-logo-box">
         <img class="fm-clue-logo" src="${visual.logo}" alt="Logo ${visual.name}" loading="eager"
           onerror="this.closest('.fm-clue-logo-box').classList.add('logo-error');this.remove()">
         <span class="fm-clue-logo-fallback" aria-hidden="true">⚽</span>
       </div>`
    : `<div class="fm-clue-icon" aria-hidden="true">${visual.icon}</div>`;

  return `
    <div class="fm-clue-card fm-clue-${visual.type}">
      ${visualMarkup}
      <div class="fm-clue-label">${clueLabel}</div>
    </div>
  `;
}

const FOOTBALLMIND_WINNING_LINES = [
  ["0-0", "0-1", "0-2"], ["1-0", "1-1", "1-2"], ["2-0", "2-1", "2-2"],
  ["0-0", "1-0", "2-0"], ["0-1", "1-1", "2-1"], ["0-2", "1-2", "2-2"],
  ["0-0", "1-1", "2-2"], ["0-2", "1-1", "2-0"]
];

function findWinningLine(answers, player) {
  const size = state.rows.length === 5 ? 5 : 3;
  const lines = [];
  for (let i = 0; i < size; i++) {
    lines.push(Array.from({length:size}, (_,c) => i+'-'+c));
    lines.push(Array.from({length:size}, (_,r) => r+'-'+i));
  }
  lines.push(Array.from({length:size}, (_,i) => i+'-'+i));
  lines.push(Array.from({length:size}, (_,i) => i+'-'+(size-1-i)));
  return lines.find((line) =>
    line.every((key) => Number(answers[key]?.owner) === Number(player))
  ) || null;
}

function setScoreRowPlayerName(row, player) {
  const playerName = state.players[player].name;

  // Ondersteun zowel de huidige als oudere HTML-versies van het scorebord.
  const explicitName = row.querySelector(
    ".fm-score-name, .score-name, [data-player-name], .player-name"
  );
  if (explicitName) {
    explicitName.textContent = playerName;
    return;
  }

  // In sommige versies staat "Speler 1/2" als losse tekst in de score-row.
  // Vervang alleen zo'n exact label, zonder score/pion of andere tekst aan te raken.
  const walker = document.createTreeWalker(row, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    const text = String(node.nodeValue || "").trim();
    if (text === `Speler ${player}`) {
      node.nodeValue = node.nodeValue.replace(`Speler ${player}`, playerName);
      return;
    }
  }
}


function findTurnPanel() {
  const titles = [...document.querySelectorAll(".fm-panel-title, h2, h3, h4, .panel-title")];
  const title = titles.find((element) => normalise(element.textContent).trim() === "beurt");
  if (!title) return null;

  let panel = title.closest(".fm-panel, .panel, aside, section, div");
  if (!panel) panel = title.parentElement;
  return panel ? { panel, title } : null;
}

function ensureTopTurnBanner() {
  let banner = document.getElementById("fmTopTurnBanner");
  if (!banner) {
    banner = document.createElement("div");
    banner.id = "fmTopTurnBanner";
    banner.setAttribute("aria-live", "polite");
    (document.querySelector(".fm-pitch-shell") || document.body).prepend(banner);
  }
  return banner;
}

function ensureTurnRoster() {
  const found = findTurnPanel();
  if (!found) return null;
  const { panel, title } = found;

  let roster = document.getElementById("fmTurnRoster");
  if (!roster) {
    // De bestaande statische "Speler 1 / Speler 2"-inhoud verbergen.
    [...panel.children].forEach((child) => {
      if (child !== title && child.id !== "fmTurnRoster") child.style.display = "none";
    });

    roster = document.createElement("div");
    roster.id = "fmTurnRoster";
    roster.innerHTML = `
      <div class="fm-turn-roster-row player-1" data-fm-roster-player="1">
        <div class="fm-turn-roster-pawn"></div>
        <div class="fm-turn-roster-name"></div>
        <div class="fm-turn-roster-score">0</div>
      </div>
      <div class="fm-turn-roster-row player-2" data-fm-roster-player="2">
        <div class="fm-turn-roster-pawn"></div>
        <div class="fm-turn-roster-name"></div>
        <div class="fm-turn-roster-score">0</div>
      </div>
      <div id="fmTurnRosterStatus"></div>`;
    title.insertAdjacentElement("afterend", roster);
  }
  return roster;
}

function ensureRulesUI() {
  ensureTopTurnBanner();
  ensureTurnRoster();
  const rows = [...document.querySelectorAll(".fm-score-row")].slice(0, 2);
  rows.forEach((row, index) => {
    const player = index + 1;
    row.dataset.player = String(player);
    setScoreRowPlayerName(row, player);
    const dot = row.querySelector(".fm-score-dot");
    if (dot) {
      dot.innerHTML = footballMindPawnImage(state.players[player].pawn);
      dot.setAttribute("aria-label", `Pion van ${state.players[player].name}`);
      dot.style.display = "grid";
      dot.style.placeItems = "center";
      dot.style.fontSize = "19px";
    }
  });

  const turnCard = document.querySelector(".fm-turn-card") || findTurnPanel()?.panel;
  if (turnCard && !document.getElementById("fmCurrentTurn")) {
    const currentTurn = document.createElement("div");
    currentTurn.id = "fmCurrentTurn";
    currentTurn.setAttribute("aria-live", "polite");
    currentTurn.style.cssText = [
      "margin:8px 8px 10px",
      "padding:10px 9px",
      "border:1px solid rgba(224,174,69,.62)",
      "border-radius:9px",
      "background:linear-gradient(180deg,rgba(101,31,43,.88),rgba(51,17,24,.92))",
      "box-shadow:0 7px 18px rgba(0,0,0,.28),inset 0 0 16px rgba(226,180,76,.06)",
      "color:#ffe6a1",
      "font-family:Georgia,serif",
      "font-size:13px",
      "font-weight:900",
      "letter-spacing:.04em",
      "text-align:center"
    ].join(";");
    turnCard.prepend(currentTurn);
  }



  const howToTitle = [...document.querySelectorAll(".fm-panel-title")]
    .find((title) => normalise(title.textContent).includes("hoe het werkt"));
  const howTo = howToTitle?.closest(".fm-panel")?.querySelector(".fm-howto");
  if (howTo && howTo.dataset.rulesVersion !== "3") {
    howTo.dataset.rulesVersion = "3";
    howTo.innerHTML = `
      <p>🔎 Kies een speler die bij <strong>rij én kolom</strong> past.</p>
      <p>✓ Goed antwoord? Het vak wordt jouw kleur en de beurt wisselt.</p>
      <p>↻ Fout antwoord of passen? De tegenstander is aan de beurt.</p>
      <p>🤝 Passen beide spelers achter elkaar? Kies samen voor remise of speel verder.</p>
      <p>🏆 Wie als eerste <strong>3 op een rij</strong> heeft, wint.</p>`;
  }

  if (!document.getElementById("fmWinnerModal")) {
    const modal = document.createElement("div");
    modal.id = "fmWinnerModal";
    modal.setAttribute("aria-hidden", "true");
    modal.innerHTML = `
      <div class="fm-winner-backdrop"></div>
      <section class="fm-winner-card" role="dialog" aria-modal="true" aria-labelledby="fmWinnerTitle">
        <div class="fm-winner-cup" aria-hidden="true">🏆</div>
        <div class="fm-winner-kicker">FootballMind</div>
        <h2 class="fm-winner-title" id="fmWinnerTitle">Speler 1 wint!</h2>
        <div class="fm-winner-sub" id="fmWinnerSub">Drie op een rij. Het bord is van jou.</div>
        <div class="fm-winner-actions">
          <button class="fm-winner-btn" id="fmViewBoard" type="button">Bekijk bord</button>
          <button class="fm-winner-btn primary" id="fmPlayAgain" type="button">Opnieuw spelen</button>
        </div>
      </section>`;
    document.body.appendChild(modal);
    const missed = document.createElement("button");
    missed.className = "fm-winner-btn";
    missed.textContent = "Gemiste antwoorden";
    missed.addEventListener("click", showMissedFootballMindAnswers);
    modal.querySelector(".fm-winner-actions").appendChild(missed);
    modal.querySelector("#fmViewBoard").addEventListener("click", closeWinnerModal);
    modal.querySelector("#fmPlayAgain").addEventListener("click", () => refreshBoardWithEmotion(false));
  }
}

function updateTurnUI() {
  FootballMindDuelStats.update();
  if (state.mode === "solo") return FootballMindSolo.update();
  ensureRulesUI();
  const rules = document.querySelector('.fm-howto');
  if (rules) rules.innerHTML = '<p>Zoek een speler die bij rij en kolom past.</p><p>Na een antwoord of passen wisselt de beurt.</p><p>' + (state.mode === 'teams' ? 'Vijf op een rij wint: horizontaal, verticaal of diagonaal.' : 'Drie op een rij wint: horizontaal, verticaal of diagonaal.') + '</p><p>Na twee passen kunnen jullie remise afspreken.</p>';
  const playerCounts = { 1: 0, 2: 0 };
  Object.values(state.answers).forEach((answer) => {
    if (answer?.owner === 1 || answer?.owner === 2) playerCounts[answer.owner] += 1;
  });

  document.querySelectorAll(".fm-score-row").forEach((row, index) => {
    const player = Number(row.dataset.player || index + 1);
    setScoreRowPlayerName(row, player);
    row.classList.toggle("fm-active-turn", !state.gameOver && player === state.currentPlayer);
    row.classList.toggle("active", !state.gameOver && player === state.currentPlayer);
    const score = row.querySelector(".fm-score-value");
    if (score) score.textContent = String(playerCounts[player] || 0);

    let label = row.querySelector(".fm-turn-label");
    if (!label) {
      label = document.createElement("div");
      label.className = "fm-turn-label";
      row.appendChild(label);
    }
    label.textContent = !state.gameOver && player === state.currentPlayer ? "Aan de beurt" : "";
  });

  const roster = ensureTurnRoster();
  if (roster) {
    [1, 2].forEach((player) => {
      const row = roster.querySelector(`[data-fm-roster-player="${player}"]`);
      if (!row) return;
      const info = state.players[player];
      const pawn = row.querySelector(".fm-turn-roster-pawn");
      const name = row.querySelector(".fm-turn-roster-name");
      const score = row.querySelector(".fm-turn-roster-score");
      if (pawn) pawn.innerHTML = footballMindPawnImage(info.pawn);
      if (name) name.textContent = info.name;
      if (score) score.textContent = String(playerCounts[player] || 0);
      row.classList.toggle("active", !state.gameOver && state.currentPlayer === player);
    });

    const status = roster.querySelector("#fmTurnRosterStatus");
    if (status) {
      if (state.gameOver) {
        status.textContent = state.winner
          ? `🏆 ${state.players[state.winner].name} heeft gewonnen`
          : "Wedstrijd afgelopen";
      } else if (state.matchStarted) {
        const active = state.players[state.currentPlayer];
        status.innerHTML = `${footballMindPawnImage(active.pawn, "fm-turn-inline-pawn")}<span>${escapeHtmlAttribute(active.name)} is aan de beurt</span>`;
      } else {
        status.textContent = "Klaar voor de aftrap";
      }
    }
  }

  const topTurn = ensureTopTurnBanner();
  if (topTurn) {
    if (state.gameOver) {
      topTurn.textContent = state.winner
        ? `🏆 ${state.players[state.winner].name} heeft gewonnen`
        : "Wedstrijd afgelopen";
    } else if (state.matchStarted) {
      const active = state.players[state.currentPlayer];
      topTurn.innerHTML = `${footballMindPawnImage(active.pawn, "fm-turn-inline-pawn")}<span>${escapeHtmlAttribute(active.name)} is aan de beurt</span>`;
    } else {
      topTurn.textContent = "⚽ Klaar voor de aftrap";
    }
  }

  const currentTurn = document.getElementById("fmCurrentTurn");
  if (currentTurn) {
    if (state.gameOver) {
      currentTurn.textContent = state.winner
        ? `🏆 ${state.players[state.winner].name} heeft gewonnen`
        : "Wedstrijd afgelopen";
    } else if (state.matchStarted) {
      const active = state.players[state.currentPlayer];
      currentTurn.innerHTML = `${footballMindPawnImage(active.pawn, "fm-turn-inline-pawn")}<span>${escapeHtmlAttribute(active.name)} is aan de beurt</span>`;
    } else {
      currentTurn.textContent = "Klaar voor de aftrap";
    }
  }

  const passButton = document.getElementById("fmPassTurn");
  if (passButton) passButton.disabled = state.mode === "solo" || state.gameOver || !state.matchStarted;
}

function switchTurn() {
  if (state.mode === "solo") return;
  if (state.gameOver) return;
  state.currentPlayer = state.currentPlayer === 1 ? 2 : 1;
  updateTurnUI();
}

function showDrawOffer() {
  if (state.mode === "solo") return;
  if (state.gameOver || !state.matchStarted || document.getElementById("fmDrawOffer")) return;
  const modal = document.createElement("div");
  modal.id = "fmDrawOffer";
  modal.className = "fm-draw-offer";
  modal.innerHTML = `
    <div class="fm-draw-backdrop"></div>
    <section class="fm-draw-card" role="dialog" aria-modal="true" aria-labelledby="fmDrawTitle">
      <div class="fm-draw-icon">🤝</div>
      <h2 id="fmDrawTitle">Remise voorstellen?</h2>
      <p>Jullie hebben allebei achter elkaar gepast. Willen jullie de wedstrijd in een gelijkspel beëindigen?</p>
      <div class="fm-draw-actions">
        <button type="button" id="fmContinueGame">Verder spelen</button>
        <button type="button" id="fmAcceptDraw">Remise accepteren</button>
      </div>
    </section>`;
  document.body.appendChild(modal);
  modal.querySelector("#fmContinueGame").addEventListener("click", () => {
    modal.remove();
    state.consecutivePasses = 0;
    showMessage("De wedstrijd gaat verder!");
    updateTurnUI();
  });
  modal.querySelector("#fmAcceptDraw").addEventListener("click", () => {
    modal.remove();
    state.consecutivePasses = 0;
    state.gameOver = true;
    state.winner = null;
    updateTurnUI();
    renderBoard();
    showMessage("🤝 Remise · beide spelers akkoord.");
    showEndGameModal("agreed-draw");
  });
  modal.querySelector("#fmContinueGame").focus();
}

function closeWinnerModal() {
  const modal = document.getElementById("fmWinnerModal");
  if (!modal) return;
  modal.classList.remove("open");
  modal.setAttribute("aria-hidden", "true");
}

function showEndGameModal(type, player = null) {
  ensureRulesUI();
  const modal = document.getElementById("fmWinnerModal");
  const title = document.getElementById("fmWinnerTitle");
  const sub = document.getElementById("fmWinnerSub");
  if (!modal || !title || !sub) return;

  if (type === "win") {
    title.textContent = `${state.players[player].pawn} ${state.players[player].name} wint!`;
    sub.textContent = state.mode === "teams" ? "Vijf op een rij. Jullie team wint!" : "Drie op een rij. Het bord is van jou.";
  } else {
    title.textContent = "Gelijkspel";
    sub.textContent = type === "agreed-draw" ? "Beide spelers hebben na twee opeenvolgende passen voor remise gekozen." : "Het bord is vol zonder drie op een rij.";
  }

  modal.classList.add("open");
  modal.setAttribute("aria-hidden", "false");
}

function finishGameAfterCorrectAnswer(player) {
  if (state.mode === "solo") return FootballMindSolo.afterAnswer();
  const winningLine = findWinningLine(state.answers, player);
  if (winningLine) {
    state.gameOver = true;
    state.winner = player;
    state.winningLine = winningLine;
    state.revealWinningLine = false;
    updateTurnUI();
    showMessage(state.players[player].name + (state.mode === "teams" ? " heeft vijf op een rij!" : " heeft drie op een rij!"));
    renderBoard();

    window.setTimeout(() => {
      if (!state.gameOver || state.winner !== player) return;
      state.revealWinningLine = true;
      state.winningLine.forEach((key) => {
        document.querySelector(`.answer[data-key="${key}"]`)?.classList.add("fm-winning-cell");
      });
      showEndGameModal("win", player);
    }, 1000);
    return true;
  }

  if (Object.keys(state.answers).length === state.rows.length * state.columns.length) {
    state.gameOver = true;
    updateTurnUI();
    showMessage("Gelijkspel · het bord is vol.");
    renderBoard();
    window.setTimeout(() => {
      if (state.gameOver && !state.winner) showEndGameModal("draw");
    }, 1000);
    return true;
  }

  return false;
}

function renderBoard() {
  const board = getElement("board");

  board.classList.toggle("fm-game-over", state.gameOver);

  board.innerHTML = '<div class="cell corner"><div class="fm-corner-ball">⚽</div></div>';
  board.innerHTML += state.columns
    .map((column) => `<div class="cell clue">${fmClueMarkup(column)}</div>`)
    .join("");

  state.rows.forEach((row, rowIndex) => {
    board.insertAdjacentHTML("beforeend", `<div class="cell clue">${fmClueMarkup(row)}</div>`);

    state.columns.forEach((column, columnIndex) => {
      const key = `${rowIndex}-${columnIndex}`;
      const answer = state.answers[key];
      const answerName = answer && typeof answer === "object" ? answer.name : answer;
      const answerImage = answer && typeof answer === "object" ? answer.image : "";
      const ownerClass = answer?.owner ? `owner-${answer.owner}` : "";
      const winningClass = state.revealWinningLine && state.winningLine.includes(key) ? "fm-winning-cell" : "";
      const justCorrect = state.justCorrect === key ? "just-correct" : "";
      const content = answer
        ? `${answerImage
             ? `<span class="fm-correct-photo-wrap">
                  <img class="fm-correct-photo" src="${escapeHtmlAttribute(answerImage)}" alt="${escapeHtmlAttribute(answerName)}" onerror="this.closest('.fm-correct-photo-wrap').remove()">
                  <span class="fm-correct-photo-check" aria-hidden="true">✓</span>
                </span>`
             : `<span class="fm-correct-check">✓</span>`}
           <span class="fm-correct-label">GOED</span>
           <strong class="fm-correct-name">${escapeHtmlAttribute(cleanPlayerName(answerName))}</strong>`
        : `<span class="fm-empty-plus">＋</span><span>Kies een speler</span>`;

      board.insertAdjacentHTML(
        "beforeend",
        `<button type="button" class="cell answer ${answer ? "correct" : "empty"} ${ownerClass} ${winningClass} ${justCorrect}" data-key="${key}" ${state.gameOver ? "disabled" : ""}>${content}</button>`
      );
    });
  });

  board.querySelectorAll(".answer.empty").forEach((cell) => {
    cell.addEventListener("click", () => openPlayerSearch(cell.dataset.key));
  });

  const filled = getElement("filled");
  if (filled) filled.textContent = Object.keys(state.answers).length;
  updateTurnUI();
}

function showMessage(message, error = false) {
  const element = getElement("message");
  if (!element) return;
  element.textContent = message;
  element.style.color = error ? "#ff9b72" : "#e8c56a";
  element.classList.remove("fm-message-pop");
  void element.offsetWidth;
  element.classList.add("fm-message-pop");
}



function combinedPlayerProfile(records, fallbackName = "") {
  const profile = {
    name: fallbackName,
    image: "",
    clubs: [],
    internationalTeams: [],
    awards: [],
    competitions: []
  };

  const fields = ["clubs", "internationalTeams", "awards", "competitions"];

  (records || []).forEach((player) => {
    if (!profile.name && player.name) profile.name = cleanPlayerName(player.name);
    if (!profile.image && playerPhotoUrl(player)) profile.image = playerPhotoUrl(player);

    fields.forEach((field) => {
      (player[field] || []).forEach((value) => {
        if (!profile[field].some((existing) => normalise(existing) === normalise(value))) {
          profile[field].push(value);
        }
      });
    });
  });

  return profile;
}

function finishWrongAttempt(playerName, cellKey) {
  if (state.mode === "solo") {
    showPlayerModalFeedback(`${playerName} past niet bij dit vak. Probeer opnieuw; de tijd loopt door.`);
    return;
  }
  FootballMindDuelStats.answer("wrong");
  const modal = document.getElementById("playerSearchModal");
  if (modal) modal.classList.remove("open");

  state.selected = null;
  state.consecutivePasses = 0;

  showMessage(`✕ ${playerName} is fout voor ${state.players[state.currentPlayer].name} · beurt voorbij`, true);

  const cell = document.querySelector(`.answer[data-key="${cellKey}"]`);
  if (cell) {
    cell.classList.remove("just-wrong");
    void cell.offsetWidth;
    cell.classList.add("just-wrong");
    window.setTimeout(() => cell.classList.remove("just-wrong"), 520);
  }

  switchTurn();
}

function showPlayerModalFeedback(message, type = "error") {
  const feedback = document.getElementById("fmPlayerFeedback");
  const dialog = document.querySelector("#playerSearchModal .fm-player-dialog");

  if (feedback) {
    feedback.textContent = message;
    feedback.className = `fm-player-feedback ${type} show`;
  }

  if (type === "error" && dialog) {
    dialog.classList.remove("wrong-answer");
    void dialog.offsetWidth;
    dialog.classList.add("wrong-answer");
    window.setTimeout(() => dialog.classList.remove("wrong-answer"), 380);
  }
}

async function submitAnswer(selection = null, options = {}) {
  const attemptedCell = state.selected;
  const input = document.getElementById("fmPlayerSearchInput");
  const rawName = typeof selection === "object" ? selection?.name : selection;
  const query = options.query ?? input?.value ?? rawName ?? "";
  let playerId = typeof selection === "object" ? selection?.id : selection;
  if ((!selection || typeof selection !== "object") && !Object.hasOwn(state.database.playerLookup, playerId || "")) {
    const candidates = state.database.nameLookup[normalise(cleanPlayerName(rawName || input?.value))] || [];
    playerId = candidates.length === 1 ? state.database.players[candidates[0]].id : null;
  }
  const [rowIndex, columnIndex] = (attemptedCell || "").split("-").map(Number);
  const result = FootballMindData.evaluateAnswer(state.database, {
    playerId, query, row: state.rows[rowIndex], column: state.columns[columnIndex],
    cellAvailable: Boolean(attemptedCell && !state.answers[attemptedCell]),
    gameOver: state.gameOver, usedPlayerIds: state.usedPlayerNames
  });
  result.debug.versions.cache = FOOTBALLMIND_DB_CACHE.version;
  result.debug.versions.cacheKey = FOOTBALLMIND_DB_CACHE.key;
  window.FootballMindLastAnswerDebug = result.debug;
  if (!result.accepted) {
    console.warn("FootballMind antwoord afgewezen", result.debug);
    if (["row_mismatch", "column_mismatch", "already_used"].includes(result.reason)) {
      const label = result.player?.name || rawName || "Onbekende speler";
      finishWrongAttempt(result.reason === "already_used" ? label + " is al gebruikt" : label, attemptedCell);
    } else {
      const messages = {
        player_not_found: "Kies de bedoelde speler uit de zoekresultaten.",
        cell_unavailable: "Klik eerst op een leeg vak.",
        game_over: "Deze wedstrijd is afgelopen.",
        index_mismatch: "De spelersindex klopt niet. Herlaad het spel om de database opnieuw op te bouwen."
      };
      showPlayerModalFeedback(messages[result.reason] || "Het antwoord kon niet worden gecontroleerd.");
    }
    return result;
  }
  const validProfile = result.player;
  const displayName = validProfile.name;
  const usedNameKey = validProfile.id;
  state.consecutivePasses = 0;
  FootballMindDuelStats.answer("correct");
  const claimingPlayer = state.currentPlayer;
  const photoSource = validProfile;
  state.answers[attemptedCell] = {
    playerId: validProfile.id,
    name: displayName,
    image: validProfile.image || playerPhotoUrl(photoSource) || "",
    owner: claimingPlayer
  };
  state.usedPlayerNames.add(usedNameKey);
  state.justCorrect = attemptedCell;

  document.getElementById("playerSearchModal")?.classList.remove("open");
  state.selected = null;

  showMessage(`✓ ${displayName} is goed voor ${state.players[claimingPlayer].name}!`);
  renderBoard();

  const gameFinished = finishGameAfterCorrectAnswer(claimingPlayer);
  if (!gameFinished) switchTurn();

  if (!state.answers[attemptedCell].image) {
    resolvePlayerPhoto(photoSource).then((url) => {
      if (!url || !state.answers[attemptedCell] || state.answers[attemptedCell].name !== displayName) return;
      state.answers[attemptedCell].image = url;
      renderBoard();
    });
  }

  window.setTimeout(() => {
    if (state.justCorrect === attemptedCell) {
      state.justCorrect = null;
      const cell = document.querySelector(`.answer[data-key="${attemptedCell}"]`);
      if (cell) cell.classList.remove("just-correct");
    }
  }, 850);
  return result;
}

function removeLegacyAnswerControls() {
  const answer = getElement("answer");
  const submit = getElement("submit");
  const suggestions = getElement("suggestions");

  if (suggestions) suggestions.remove();
  if (submit) submit.remove();
  if (answer) answer.remove();

  document
    .querySelectorAll('label[for="answer"]')
    .forEach((label) => label.remove());

  // Oude zoek-UI mag nergens meer zichtbaar blijven.
  document.querySelectorAll(".searchbox").forEach((box) => {
    if (!box.querySelector("#difficulty")) box.remove();
  });

  /*
   * Sommige versies hebben "Speler" als gewone tekst in een wrapper.
   * Laat de wrapper staan zolang daar ook Niveau in zit; CSS/HTML kunnen
   * we later netjes opschonen.
   */
}


const FOOTBALLMIND_DB_CACHE = {
  dbName: "FootballMindCache",
  storeName: "database",
  key: "game-database-v7",
  version: 5,
  expectedDataRevision: FootballMindData.REVISION,
  maxAgeMs: 1000 * 60 * 60 * 24 * 30 // 30 dagen; versiecheck kan later verfijnd worden
};

function openFootballMindCache() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(FOOTBALLMIND_DB_CACHE.dbName, FOOTBALLMIND_DB_CACHE.version);
    let blocked = false;

    request.onupgradeneeded = () => {
      const db = request.result;
      if (db.objectStoreNames.contains(FOOTBALLMIND_DB_CACHE.storeName)) {
        db.deleteObjectStore(FOOTBALLMIND_DB_CACHE.storeName);
      }
      if (!db.objectStoreNames.contains(FOOTBALLMIND_DB_CACHE.storeName)) {
        db.createObjectStore(FOOTBALLMIND_DB_CACHE.storeName);
      }
    };

    request.onblocked = () => {
      blocked = true;
      reject(new Error("Een oudere FootballMind-tab houdt de vorige cache open; de actuele bronnen worden opnieuw opgebouwd."));
    };
    request.onsuccess = () => {
      const db = request.result;
      if (blocked) { db.close(); return; }
      db.onversionchange = () => db.close();
      resolve(db);
    };
    request.onerror = () => reject(request.error);
  });
}

async function getCachedFootballMindDatabase() {
  try {
    const db = await openFootballMindCache();

    return await new Promise((resolve, reject) => {
      const tx = db.transaction(FOOTBALLMIND_DB_CACHE.storeName, "readonly");
      const store = tx.objectStore(FOOTBALLMIND_DB_CACHE.storeName);
      const request = store.get(FOOTBALLMIND_DB_CACHE.key);

      request.onsuccess = () => {
        const cached = request.result;
        if (!cached || !cached.data || !cached.savedAt) {
          resolve(null);
          return;
        }

        if (cached.data.version !== FootballMindData.VERSION || cached.data.normalizationVersion !== FOOTBALLMIND_DB_CACHE.expectedDataRevision) {
          resolve(null);
          return;
        }

        const age = Date.now() - cached.savedAt;
        if (age > FOOTBALLMIND_DB_CACHE.maxAgeMs) {
          resolve(null);
          return;
        }

        resolve(cached);
      };

      request.onerror = () => reject(request.error);
    });
  } catch (error) {
    console.warn("FootballMind cache lezen mislukt:", error);
    return null;
  }
}

async function saveFootballMindDatabaseToCache(data) {
  try {
    const db = await openFootballMindCache();

    await new Promise((resolve, reject) => {
      const tx = db.transaction(FOOTBALLMIND_DB_CACHE.storeName, "readwrite");
      const store = tx.objectStore(FOOTBALLMIND_DB_CACHE.storeName);

      const request = store.put(
        {
          data,
          savedAt: Date.now()
        },
        FOOTBALLMIND_DB_CACHE.key
      );

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  } catch (error) {
    console.warn("FootballMind cache opslaan mislukt:", error);
  }
}

function hydratePrebuiltGameIndexes(gameDb) {
  state.clueIndex = new Map();
  state.clueSets = new Map();
  state.categoryCache = new Map();
  state.availableCache = new Map();
  state.nameIndex = new Map();
  state.searchPlayers = [];

  const players = gameDb.players || [];
  state.playerIndex = new Map(Object.entries(gameDb.playerLookup || {}).map(([id, index]) => [id, players[index]]));
  for (const [source, target] of [["clubPlayers", "clubIndex"], ["countryPlayers", "countryIndex"], ["competitionPlayers", "competitionIndex"]]) {
    state[target] = new Map(Object.entries(gameDb[source] || {}).map(([key, indexes]) => [key, indexes.map((index) => players[index])]));
  }

  Object.entries(gameDb.cluePlayers || {}).forEach(([key, indexes]) => {
    const list = indexes.map((index) => players[index]).filter(Boolean);
    state.clueIndex.set(key, list);
    state.clueSets.set(key, new Set(list));
  });

  Object.entries(gameDb.nameLookup || {}).forEach(([key, indexes]) => {
    state.nameIndex.set(
      key,
      indexes.map((index) => players[index]).filter(Boolean)
    );
  });

  state.searchPlayers = players.map(FootballMindData.searchEntry);

  state.indexesReady = true;
}

async function loadGameDatabase() {
  // Always validate against fresh source files; a stale generated file is never authoritative.
  const files = ["FootballMind_database.json", "FootballMind_legends.json", "FootballMind_career_corrections.json", "FootballMind_club_competitions.json"];
  const texts = await Promise.all(files.map(async (file) => {
    for (const prefix of ["../data/", "data/"]) {
      const response = await fetch(prefix + file, { cache: "no-store" });
      if (response.ok) return response.text();
    }
    throw new Error("Databasebron ontbreekt: " + file);
  }));
  let inputRevision = null;
  if (globalThis.crypto?.subtle) {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(texts.join("\n")));
    inputRevision = Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
  }
  const cached = await getCachedFootballMindDatabase();
  let data = inputRevision && cached?.data?.inputRevision === inputRevision
    ? cached.data
    : FootballMindData.build(...texts.map((text) => JSON.parse(text)));
  data.inputRevision = inputRevision;
  let audit;
  try { audit = FootballMindData.audit(data); }
  catch (error) {
    if (data !== cached?.data) throw error;
    audit = { failed: 1 };
  }
  if (audit.failed && data === cached?.data) {
    data = FootballMindData.build(...texts.map((text) => JSON.parse(text)));
    data.inputRevision = inputRevision;
    audit = FootballMindData.audit(data);
  }
  window.FootballMindAudit = audit;
  console.table(audit.checks);
  if (audit.failed) throw new Error("Database-audit mislukt: " + audit.checks.filter((check) => !check.ok).map((check) => check.label).join(", "));
  if (inputRevision && data !== cached?.data) await saveFootballMindDatabaseToCache(data);
  return data;
}


async function startGame() {
  ensureDatabaseLoader();
  setLoadProgress(8, "Snelle game-database laden…");

  try {
    const gameDb = await loadGameDatabase();
    setLoadProgress(65, "Spelers en koppelingen klaarzetten…");
    enrichFootballMindIdentities(gameDb);
    state.database = gameDb;
    hydratePrebuiltGameIndexes(gameDb);
    setLoadProgress(92, "Wedstrijd voorbereiden…");
    getElement("sourceStatus").textContent =
      gameDb.players.length + " spelers · audit " + window.FootballMindAudit.passed + "/" + window.FootballMindAudit.checks.length + " geslaagd";

    markStartScreenReady();

    setLoadProgress(100, "Klaar. Aftrappen!");
    window.setTimeout(() => {
      document.getElementById("fmDatabaseLoader")?.classList.add("done");
    }, 140);
  } catch (error) {
    console.error(error);
    document.getElementById("fmDatabaseLoader")?.classList.add("done");
    getElement("sourceStatus").textContent = "Game database niet gevonden";
    const startButton = document.getElementById("fmStartMatch");
    if (startButton) {
      startButton.disabled = true;
      startButton.textContent = "Database niet gevonden";
    }
    const startText = document.getElementById("fmStartLoadText");
    if (startText) startText.textContent = "De spelersdatabase kon niet worden geladen.";
    showMessage(
      "Maak eerst data/FootballMind_game_database.json met de Game Database Builder.",
      true
    );
  }
}

getElement("newGame").addEventListener("click", showStartScreen);

if (getElement("difficulty")) {
  const difficultySelect = getElement("difficulty");
  const syncLevelText = () => {
    const label = getElement("levelText");
    if (!label) return;
    const names = { easy: "MAKKELIJK", medium: "GEMIDDELD", hard: "MOEILIJK" };
    label.textContent = names[difficultySelect.value] || difficultySelect.value.toUpperCase();
  };
  difficultySelect.addEventListener("change", () => {
    syncLevelText();
    if (state.matchStarted) refreshBoardWithEmotion(true);
  });
  syncLevelText();
}


window.FootballMindCache = {
  async clear() {
    try {
      const db = await openFootballMindCache();
      await new Promise((resolve, reject) => {
        const tx = db.transaction(FOOTBALLMIND_DB_CACHE.storeName, "readwrite");
        const request = tx.objectStore(FOOTBALLMIND_DB_CACHE.storeName).delete(FOOTBALLMIND_DB_CACHE.key);
        request.onsuccess = () => resolve();
        request.onerror = () => reject(request.error);
      });
      console.log("FootballMind cache gewist.");
    } catch (error) {
      console.warn("Cache wissen mislukt:", error);
    }
  }
};

ensureGameFeelStyles();
ensureStartScreen();
removeLegacyAnswerControls();
startGame();

// Remise-keuze sluit visueel aan bij het bestaande FootballMind-thema.
